<template>
  <back-home-btn>
    <template>
      <div style="display: flex; justify-content: space-between">
        <div class="box-wrap" id="chartsBox" />
        <div class="json-wrap">
          {{ jsonData }}
        </div>
      </div>
    </template>
  </back-home-btn>
</template>

<script>
import { getEchartData } from "@/api/allRequset";

export default {
  name: "box2",
  components: {},
  mixins: [],
  props: {},
  computed: {},
  watch: {},
  filters: {},
  data() {
    return {
      timeKey: "createTime",
      valueKey: "totalIn",
      chartsTop: 30,
      jsonData: require("/public/fiveMinuteDemoData").default,
    };
  },
  methods: {
    /**
     * @Event 获取折线图的数据
     * @param {*} obj.areaCode 区域编号 (1 道路 2 区域 传的都是 areaCode)
     * @param {*} obj.checkTypes 查询类型（1实时 2预测 3过去）
     * @param {*} obj.roadCode 路段编号
     * @param {*} obj.selectTime 选择时间
     * @description:
     * @author: mhf
     * @time: 2024-02-02 09:48:06
     **/
    getBox2Data(params) {
      return new Promise((resolve, reject) => {
        // areaType：1 道路 2 区域
        getEchartData(params).then((resOld) => {
          let res = resOld.data;
          if (res.code === 1) {
            this.chartsData = {
              // 初始化数据（五分钟一个点，24 * 12）
              roadNorm: Array.from({ length: 24 * 12 }, () => null), // Initialize with [null, null, ..., null]
              time: Array.from({ length: 24 * 12 }, (_, i) => i / 12), // Initialize with [0, 0.0833, ..., 23.9167]
            };
            if (res.data && res.data.length > 0) {
              res.data.forEach((item) => {
                const timeValue = new Date(item[this.timeKey]);
                const index = Math.floor(
                  timeValue.getHours() * 12 + timeValue.getMinutes() / 5
                );
                if (index >= 0 && index < this.chartsData.time.length) {
                  this.chartsData.roadNorm[index] = item[this.valueKey];
                }
              });
              const maxNumber = Math.max(
                ...res.data.map((obj) => obj[this.valueKey])
              );
              // this.chartsTop = maxNumber > 0.8 ? 40 : 6; // todo
            }
            resolve();
          } else {
            reject();
          }
        });
      })
        .then(() => {
          if (this.chartsData) {
            this.initChartsBox();
          }
        })
        .catch((e) => {
          console.warn("Error", e);
        });
    },

    initChartsBox() {
      this.option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            animation: false,
          },
          formatter: function (params) {
            const index = params[0].dataIndex;
            const hour = Math.floor(index / 12);
            const minute = (index % 12) * 5;
            const formattedHour = String(hour).padStart(2, "0");
            const formattedMinute = String(minute).padStart(2, "0");
            const timeStr = `${formattedHour}:${formattedMinute}`;
            const congestionIndex = params[0].value;
            const formattedIndex = congestionIndex?.toFixed(2) || "-";
            const circleIcon =
              '<span style="display:inline-block;margin-right:5px;border-radius:50%;width:8px;height:8px;background-color:#5470c6;"></span>';
            return `${timeStr}<br>${circleIcon} ${formattedIndex} 辆`;
          },
        },
        axisPointer: {
          link: {
            xAxisIndex: "all",
          },
        },
        dataZoom: [
          {
            show: false,
            realtime: true,
            start: 0,
            end: 100,
            // height: 14,
            xAxisIndex: [0, 1],
            zoomLock: true,
          },
          {
            type: "inside",
            realtime: true,
            start: 0,
            end: 100,
            xAxisIndex: [0, 1],
            zoomLock: true,
          },
        ],
        grid: [
          {
            top: this.chartsTop,
            bottom: 40,
            left: 40,
            right: 40,
          },
          {
            left: -10,
            right: 0,
            top: 0,
            bottom: 0,
          },
        ],
        xAxis: [
          {
            type: "category",
            boundaryGap: false,
            axisLine: {
              onZero: true,
            },
            data: this.chartsData.time,
            axisLabel: {
              formatter: function (value, index) {
                const hour = Math.floor(value);
                return hour + ":00";
              },
            },
          },
          {
            gridIndex: 1,
          },
        ],

        yAxis: [
          {
            type: "value",
            min: 0,
            // max: 1000, // todo
            name: "单位: 辆",
          },
          {
            gridIndex: 1,
          },
        ],
        series: [
          {
            name: "饱和度",
            type: "line",
            smooth: true,
            symbol: "circle",
            symbolSize: 9,
            showSymbol: false,
            lineStyle: {
              normal: {
                width: 2,
                color: "#5470c6",
              },
            },
            markPoint: {
              data: [
                {
                  type: "max",
                  name: "最大值",
                },
                {
                  type: "min",
                  name: "最小值",
                },
              ],
            },
            markArea: {
              silent: true,
              label: {
                normal: {
                  position: ["4%", "50%"],
                },
              },
              data: [],
            },
            // data: this.chartsData.roadNorm,
            data: this.chartsData.roadNorm.map((value, index) => ({
              value,
              time: this.chartsData.time[index],
            })), // 数据初始化(tooltip中使用formatter)
          },
        ],
      };
      this.myChart = this.$echarts.init(document.getElementById("chartsBox")); // 图标初始化
      this.myChart.setOption(this.option); // 渲染页面
      /* ECharts动态效果 */
      window.addEventListener("resize", () => {
        this.myChart.resize();
      });
    },
  },
  created() {},
  mounted() {
    this.getBox2Data();
  },
  destroyed() {},
};
</script>

<style lang="scss" scoped>
.box-wrap {
  width: calc(100vw - 400px);
  height: calc(100vh - 100px);
}

.json-wrap {
  flex: 1;
  height: calc(100vh - 100px);
  overflow-y: auto;
}
</style>
